// ── source: vcx/tests/xap_registry_serve_real_test.v ──
// xap_registry_serve_real_test.v — BEHAVIORAL proof of the distribution spec's
// §4.2 stage-2 claim: serving the SAME registry store over cx-store:// (CSRP)
// is a RE-HOST — artifacts, hashes, and signatures are bit-identical to the
// stage-1 git registry, and discovery works server-side with no alias verbs on
// the wire (pkg-catalog falls back to CXPath query pushdown, `//publisher`).
//
// The SERVER is `cx store-serve` (stream-4 S3: the CSRP reference server is
// retired) serving the COMMITTED file:// registry (registry/store — the
// stage-1 git registry, M2) over THE store wire: the XSP store profile. A cx
// program is the CLIENT: it opens `cx-store+xsp://127.0.0.1:PORT/registry/`,
// DISCOVERS gtin@0.1.0 via [$xap:pkg-catalog] (server-side query
// pushdown), then pkg-verify + pkg-install BY the discovered manifest hash —
// the full §3 trust chain over a real loopback socket. The asserted hashes
// are the same constants the stage-1 fixture (xap-dist-025) pins: stage 1 →
// stage 2 changed nothing.
//
// Black-box, no Docker; both processes get only loopback net.

const gtin_manifest_hash = 'sha2-256:938ccff3085fc331ad8aabb318ad80f6566bb4f2e94386b9353c405dde1e4f43'

const gtin_tree_hash = 'sha2-256:9f0e24be318275856dc8a845d1be4a5e9c02d1ff2f68919d0249d8312a08eca9'

fn xrs_cx_binary() string {
	return testenv.cx_bin()
}

// Disjoint port band (26700-26799) from the http (26400) and csrp (26600) tests.
fn xrs_pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26700 + int(salt)
}

fn xrs_write_tmp(name string, content string) string {
	p := os.join_path(os.temp_dir(), name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

// RFC 8032 TEST-2 vector — the daemon's XSP responder identity.
const xrs_host_did = 'did:key:z6MkiaMbhXHNA4eJVCCj8dbzKzTgYDKf6crKgHVHid1F1WCT'

const xrs_host_seed_hex = '4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb'

fn xrs_server_cfg(cport int, xport int, store_dir string) string {
	return '[cxstore-service
  [bind addr="127.0.0.1:${cport}"]
  [stores [store name="registry" url="file://${store_dir}"]]
  [xsp enabled=true addr="127.0.0.1:${xport}"
    [identity did="${xrs_host_did}" seed-env="CX_XRS_STORE_SEED"]
    [policy mode=floor floor="registry-reader"]]]'
}

fn xrs_client_prog(xport int) string {
	return "[?lib 'cx-xap' :as xap]\n" + "[?lib 'cx-stdlib/store' :as store]\n" +
		'[?let [= \$c [\$store:open "cx-store+xsp://127.0.0.1:${xport}/registry/"]]\n' +
		'[?let [= \$cat [\$xap:pkg-catalog \$c {name: "gtin" version: "0.1.0"}]]\n' +
		'[?let [= \$e \$cat//package]\n' +
		'[?let [= \$v [\$xap:pkg-verify \$c \$e@manifest]]\n' +
		'[?let [= \$inst [\$xap:pkg-install [xap name=wire-consumer] \$c \$e@manifest]]\n' +
		'[result [manifest \$e@manifest] [status \$v@status] [hash \$inst@hash] [name \$inst@name]]\n' +
		']]]]]\n'
}

fn test_served_registry_is_a_rehost() {
	cport := xrs_pick_port()
	xport := cport + 1
	os.setenv('CX_XRS_STORE_SEED', xrs_host_seed_hex, true)
	defer {
		os.unsetenv('CX_XRS_STORE_SEED')
	}
	store_dir := os.real_path('registry/store')
	if !os.is_dir(store_dir) {
		eprintln('SKIP: registry/store not present (run from the repo root)')
		return
	}
	cfg := xrs_write_tmp('cx_xrs_srv_${xport}.cx', xrs_server_cfg(cport, xport, store_dir))
	cli := xrs_write_tmp('cx_xrs_cli_${xport}.cx', xrs_client_prog(xport))
	srv_out := '/tmp/cx-xrs-srv.${xport}.out'
	allow := '--allow-all'

	pid_s := os.execute('${xrs_cx_binary()} store-serve --config ${cfg} ${allow} >${srv_out} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn registry server')
		return
	}
	pid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
	}
	// wait for the bootstrap HTTP health endpoint before driving the profile client
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := os.execute('curl -s -o /dev/null -w "%{http_code}" --max-time 2 http://127.0.0.1:${cport}/cx-store/v1/health')
		if r.output.trim_space() == '200' {
			up = true
			break
		}
	}
	if !up {
		eprintln('SKIP: store-serve did not become ready (log: ${os.read_file(srv_out) or { '' }})')
		return
	}

	res := os.execute('${xrs_cx_binary()} ${allow} ${cli}')
	assert res.exit_code == 0, 'client failed: ${res.output} (server log: ${os.read_file(srv_out) or {
		''
	}})'
	out := res.output
	assert out.contains('[status ok]') || out.contains("[status 'ok']"), 'verify not ok over the wire: ${out}'
	assert out.contains(gtin_manifest_hash), 'catalog did not discover the stage-1 manifest hash: ${out}'
	assert out.contains(gtin_tree_hash), 'installed tree hash differs from the stage-1 artifact: ${out}'
	assert out.contains('gtin'), 'installed package name missing: ${out}'
}

// ── source: vcx/tests/xap_source_bind_test.v ──
// xap_source_bind_test.v — BEHAVIORAL proof of the §3.1.2 event-source
// binding (#583): `[$xap:run {sources: […]}]` makes the RUNTIME own the
// fabric subscription (group offsets, batched pull, ack **after** fold);
// each received entry enters the cascade as the mapped verb, so panels stay
// folds-of-events; combined with the §3.1.1 journal binding the ingested
// commits are durable acts and a restart re-folds them; a served runtime
// pushes the re-rendered surface to /events on every ingested commit AND on
// every in-process emit (not only web intents).

const sb_host_did = 'did:key:z6MkiaMbhXHNA4eJVCCj8dbzKzTgYDKf6crKgHVHid1F1WCT' // RFC 8032 TEST 2

const sb_host_seed_hex = '4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb'

const sb_client_did = 'did:key:z6MktwupdmLXVVqTzCw4i46r4uGyosGXRnR3XjN4Zq7oMMsw' // RFC 8032 TEST 1

const sb_client_seed_hex = '9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60'

// Disjoint port band (27600-27699), after xap-journal-bind (27500-27599).
fn sb_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 80
	return 27600 + int(salt)
}

fn sb_write(dir string, name string, content string) string {
	p := os.join_path(dir, name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

fn sb_run(args string, prog string) string {
	res := os.execute('${testenv.cx_bin()} ${args} ${prog}')
	return res.output.trim_space()
}

fn sb_curl(args string) string {
	r := os.execute('curl -s --max-time 3 ${args}')
	return r.output
}

// The ingesting component: entries enter the cascade as :evidence intents,
// so the /evidence slice is the fold and the view renders each record's id.
const sb_component = '[?lib \'cx-xap\' :as xap]
[\$xap:component evid
  {bind: "/evidence"
   emits: ([do :evidence [e :element]])
   view: [?fn (\$rs) [panel [list [?for [in \$r \$rs] [yield [item \$r/evidence/id]]]]]]
   working-panel: :none}]
'

fn test_xap_source_bind_embedded_ingest_ack_and_refold() {
	tmp := os.join_path(os.temp_dir(), 'cx-xap-sbind-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	evid := 'file://${tmp}/evidence-journal'
	acts := 'file://${tmp}/acts-journal'
	src := '{fabric: "${evid}", stream: "evidence", group: "g1", verb: :evidence, actor: "ingest"}'
	jbind := '{url: "${acts}", stream: "acts"}'

	// seed the evidence stream from a plain fabric publisher (no xap).
	pub1 := sb_write(tmp, 'publish.cx', "[?lib 'cx-fabric' :as fabric]\n" +
		"[?lib 'cx-stdlib/journal' :as journal]\n" +
		'[?let [= \$j [\$journal:open "${evid}" "demo"]]\n' +
		'      [= \$f [\$fabric:open \$j]]\n' +
		'      [= \$a [\$fabric:publish \$f "evidence" [evidence [id "e1"] [kind "cro"]] {actor: "src" authority: "sim"}]]\n' +
		'      [= \$b [\$fabric:publish \$f "evidence" [evidence [id "e2"] [kind "cro"]] {actor: "src" authority: "sim"}]]\n' +
		'  [out \$b]]\n')
	pout := sb_run('--allow-read --allow-write', pub1)
	assert pout.contains('seq=2'), 'publisher did not seed two events: ${pout}'

	// worker 1: the runtime owns the subscription — after the pump drains,
	// the fold holds both records, entered as :evidence intents.
	w1 := sb_write(tmp, 'worker1.cx', sb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: ${jbind} sources: [${src}]}]]\n' +
		'      [= \$w [?sleep 2500ms]]\n' +
		'  [out [\$count [\$xap:state \$rt "/evidence"]]]]\n')
	out1 := sb_run('--allow-read --allow-write', w1)
	assert out1.contains('[out 2]'), 'runtime-owned source did not ingest+fold two entries: ${out1}'

	// worker 2 (RESTART, same group + same journal binding): the group's
	// offset is committed (ack-after-fold — nothing redelivers), and the
	// §3.1.1 acts stream re-folds BOTH ingested commits at boot. Together
	// the journal is the only hand-off in both directions.
	out2 := sb_run('--allow-read --allow-write', w1)
	assert out2.contains('[out 2]'), 'restart did not re-fold the ingested acts (or the group redelivered): ${out2}'

	// denial lane: an agent actor with no authority chain is denied by the
	// PEP — the entry is SKIPPED but ACKNOWLEDGED (deny-by-default must not
	// wedge the group), so a follow-up admissible worker on the SAME group
	// sees nothing redelivered.
	evid2 := 'file://${tmp}/evidence2-journal'
	acts2 := 'file://${tmp}/acts2-journal'
	pub2 := sb_write(tmp, 'publish2.cx', "[?lib 'cx-fabric' :as fabric]\n" +
		"[?lib 'cx-stdlib/journal' :as journal]\n" +
		'[?let [= \$j [\$journal:open "${evid2}" "demo"]]\n' +
		'      [= \$f [\$fabric:open \$j]]\n' +
		'      [= \$a [\$fabric:publish \$f "evidence" [evidence [id "e9"] [kind "cro"]] {actor: "src" authority: "sim"}]]\n' +
		'  [out \$a]]\n')
	pout2 := sb_run('--allow-read --allow-write', pub2)
	assert pout2.contains('seq=1'), 'publisher 2 did not seed: ${pout2}'
	denied_src := '{fabric: "${evid2}", stream: "evidence", group: "g2", verb: :evidence, actor: "agent:ghost"}'
	w3 := sb_write(tmp, 'worker3.cx', sb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: {url: "${acts2}", stream: "acts"} sources: [${denied_src}]}]]\n' +
		'      [= \$w [?sleep 2500ms]]\n' +
		'  [out [\$count [\$xap:state \$rt "/evidence"]]]]\n')
	out3 := sb_run('--allow-read --allow-write', w3)
	assert out3.contains('[out 0]'), 'denied ingest must fold nothing: ${out3}'
	ok_src := '{fabric: "${evid2}", stream: "evidence", group: "g2", verb: :evidence, actor: "ingest"}'
	w4 := sb_write(tmp, 'worker4.cx', sb_component +
		'[?let [= \$rt [\$xap:run {tenant: "demo" journal: {url: "${acts2}", stream: "acts"} sources: [${ok_src}]}]]\n' +
		'      [= \$w [?sleep 2000ms]]\n' +
		'  [out [\$count [\$xap:state \$rt "/evidence"]]]]\n')
	out4 := sb_run('--allow-read --allow-write', w4)
	assert out4.contains('[out 0]'), 'a denied entry must be acked past, never redelivered: ${out4}'
}

fn test_xap_source_bind_remote_live_ingest_and_sse_push() {
	if os.execute('which curl').exit_code != 0 {
		eprintln('SKIP: curl not available')
		return
	}
	cxbin := testenv.cx_bin()
	port := sb_port()
	hport := port + 100
	wport := port + 200
	tmp := os.join_path(os.temp_dir(), 'cx-xap-sbind-xsp-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	cfg := '[fabric-service
  [bind addr="127.0.0.1:${port}"]
  [health addr="127.0.0.1:${hport}"]
  [identity did="${sb_host_did}" seed-env="CX_FABRIC_SEED"]
  [policy mode="mutual"]
  [limits pending-window=16 liveness-ms=15000 request-timeout-ms=5000]
  [fabrics [fabric name="main" store="file://${tmp}/store" tenant="acme"]]
  [principals
    [principal did="${sb_client_did}"
      [grant action="publish" scope="*"]
      [grant action="consume" scope="*"]
      [grant action="observe" scope="*"]]]]'
	cfg_path := sb_write(tmp, 'fabric.service.cx', cfg)
	os.setenv('CX_FABRIC_SEED', sb_host_seed_hex, true)
	mut proc := os.new_process('/bin/sh')
	proc.set_args(['-c',
		'exec "${cxbin}" fabric-serve --config "${cfg_path}" --allow-read --allow-write --allow-net=127.0.0.1:${port} --allow-net=127.0.0.1:${hport} --allow-env >"${tmp}/daemon.log" 2>&1'])
	proc.run()
	defer {
		proc.signal_kill()
		os.unsetenv('CX_FABRIC_SEED')
		os.rmdir_all(tmp) or {}
	}
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := http.get('http://127.0.0.1:${hport}/ready') or { continue }
		if r.status_code == 200 && r.body.contains('[accepting true]') {
			up = true
			break
		}
	}
	if !up {
		out := os.read_file(os.join_path(tmp, 'daemon.log')) or { '' }
		panic('fabric-serve never came up: ${out}')
	}

	client_open := '[\$fabric:open "xsp://127.0.0.1:${port}" {tenant: "acme" did: "${sb_client_did}" seed: [\$bytes:from-hex "${sb_client_seed_hex}"]}]'
	// seed one evidence event before the worker boots.
	pub1 := sb_write(tmp, 'publish1.cx', "[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
		'[?let [= \$f ${client_open}]\n' +
		'  [\$fabric:publish \$f "evidence" [evidence [id "e1"] [kind "cro"]] {}]]\n')
	pout1 := sb_run('--allow-net=127.0.0.1:${port}', pub1)
	assert pout1.contains('seq=1'), 'remote publish 1 failed: ${pout1}'

	// the served worker: runtime-owned remote source + web serve.
	src := '{fabric: "xsp://127.0.0.1:${port}", stream: "evidence", group: "gw", verb: :evidence, actor: "ingest", tenant: "acme", did: "${sb_client_did}", seed: [\$bytes:from-hex "${sb_client_seed_hex}"]}'
	wsrv := sb_write(tmp, 'worker-serve.cx', "[?lib 'cx-stdlib/bytes' :as bytes]\n" + sb_component +
		'[?let [= \$rt [\$xap:run {tenant: "acme" sources: [${src}]}]]\n' +
		'  [\$xap:serve "http://127.0.0.1:${wport}" {runtime: \$rt}]]\n')
	pid_s := os.execute('${cxbin} --allow-net=127.0.0.1:${port} --allow-net=127.0.0.1:${wport} ${wsrv} >${tmp}/worker.log 2>&1 & echo \$!')
	wpid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${wpid} 2>/dev/null')
	}

	// the pre-boot event lands on the surface (ingest → cascade → fold → view).
	mut got1 := false
	for _ in 0 .. 60 {
		s := sb_curl('http://127.0.0.1:${wport}/surface')
		if s.contains("[item 'e1']") {
			got1 = true
			break
		}
		time.sleep(200 * time.millisecond)
	}
	wlog := os.read_file(os.join_path(tmp, 'worker.log')) or { '' }
	assert got1, 'pre-boot evidence never reached the served surface (worker log: ${wlog})'

	// live: hold an SSE reader open, publish a SECOND event from a separate
	// process — the runtime's pump must fold it AND push the re-rendered
	// surface to the held reader (§3.1.2: live media follow ingest).
	cap_file := os.join_path(tmp, 'sse.cap')
	os.execute('curl -sN --max-time 6 http://127.0.0.1:${wport}/events >${cap_file} 2>&1 & echo \$!')
	time.sleep(500 * time.millisecond)
	pub2 := sb_write(tmp, 'publish2.cx', "[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
		'[?let [= \$f ${client_open}]\n' +
		'  [\$fabric:publish \$f "evidence" [evidence [id "e2"] [kind "cro"]] {}]]\n')
	pout2 := sb_run('--allow-net=127.0.0.1:${port}', pub2)
	assert pout2.contains('seq=2'), 'remote publish 2 failed: ${pout2}'
	mut got2 := false
	for _ in 0 .. 30 {
		cap := os.read_file(cap_file) or { '' }
		if cap.contains("[item 'e2']") {
			got2 = true
			break
		}
		time.sleep(200 * time.millisecond)
	}
	cap := os.read_file(cap_file) or { '' }
	assert got2, 'ingested commit was not pushed to the held /events reader; got: ${cap}'
}

// §3.1.2 rider: an IN-PROCESS emit after boot refreshes /events subscribers
// too — push-on-commit is the cascade's, not the web bridge's.
fn test_xap_inprocess_emit_pushes_sse() {
	if os.execute('which curl').exit_code != 0 {
		eprintln('SKIP: curl not available')
		return
	}
	port := sb_port() + 90
	tmp := os.join_path(os.temp_dir(), 'cx-xap-emit-sse-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	defer {
		os.rmdir_all(tmp) or {}
	}
	srv := sb_write(tmp, 'emit-server.cx', '[?lib \'cx-xap\' :as xap]\n' +
		'[\$xap:component guestbook\n' +
		'  {bind: "/guestbook"\n' +
		'   emits: ([do :sign [name :string]])\n' +
		'   view: [?fn (\$gs) [panel [list [?for [in \$g \$gs] [yield [item \$g/name]]]]]]\n' +
		'   working-panel: :none}]\n' +
		'[?let [= \$rt [\$xap:run {tenant: "demo"}]]\n' +
		'      [= \$srv [\$xap:serve "http://127.0.0.1:${port}" {runtime: \$rt block: false}]]\n' +
		'      [= \$w1 [?sleep 1500ms]]\n' +
		'      [= \$e [\$xap:emit \$rt [do :sign [name "Iris"]]]]\n' +
		'      [= \$w2 [?sleep 8s]]\n' +
		'  [out \$e]]\n')
	pid_s := os.execute('${testenv.cx_bin()} --allow-net ${srv} >${tmp}/server.log 2>&1 & echo \$!')
	pid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
	}
	mut up := false
	for _ in 0 .. 30 {
		if sb_curl('-o /dev/null -w "%{http_code}" http://127.0.0.1:${port}/surface') == '200' {
			up = true
			break
		}
		time.sleep(100 * time.millisecond)
	}
	assert up, 'xap serve never bound on ${port}'

	cap_file := os.join_path(tmp, 'sse.cap')
	os.execute('curl -sN --max-time 5 http://127.0.0.1:${port}/events >${cap_file} 2>&1 & echo \$!')
	// the in-process emit fires ~1.5s after boot; the held reader must get
	// the post-emit surface without any web intent in the loop.
	mut got := false
	for _ in 0 .. 30 {
		cap := os.read_file(cap_file) or { '' }
		if cap.contains("[item 'Iris']") {
			got = true
			break
		}
		time.sleep(200 * time.millisecond)
	}
	cap := os.read_file(cap_file) or { '' }
	assert got, 'in-process emit did not push to the held /events reader; got: ${cap}'
}

// #593: on a runtime with BOTH a remote source and a remote §3.1.1 journal
// binding, a received batch commits through ONE pipelined append turn —
// every entry lands on the acts stream in order and folds. Pins the batch
// lane end-to-end: 6 pre-published evidence events → 6 ingested commits →
// 6 ordered acts observable by an independent client.
fn test_xap_source_batch_pipelined_appends() {
	cxbin := testenv.cx_bin()
	port := sb_port() + 45
	hport := port + 100
	tmp := os.join_path(os.temp_dir(), 'cx-xap-sbatch-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic(err) }
	cfg := '[fabric-service
  [bind addr="127.0.0.1:${port}"]
  [health addr="127.0.0.1:${hport}"]
  [identity did="${sb_host_did}" seed-env="CX_FABRIC_SEED"]
  [policy mode="mutual"]
  [limits pending-window=64 liveness-ms=15000 request-timeout-ms=5000]
  [fabrics [fabric name="main" store="file://${tmp}/store" tenant="acme"]]
  [principals
    [principal did="${sb_client_did}"
      [grant action="publish" scope="*"]
      [grant action="consume" scope="*"]
      [grant action="observe" scope="*"]]]]'
	cfg_path := sb_write(tmp, 'fabric.service.cx', cfg)
	os.setenv('CX_FABRIC_SEED', sb_host_seed_hex, true)
	mut proc := os.new_process('/bin/sh')
	proc.set_args(['-c',
		'exec "${cxbin}" fabric-serve --config "${cfg_path}" --allow-read --allow-write --allow-net=127.0.0.1:${port} --allow-net=127.0.0.1:${hport} --allow-env >"${tmp}/daemon.log" 2>&1'])
	proc.run()
	defer {
		proc.signal_kill()
		os.unsetenv('CX_FABRIC_SEED')
		os.rmdir_all(tmp) or {}
	}
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := http.get('http://127.0.0.1:${hport}/ready') or { continue }
		if r.status_code == 200 && r.body.contains('[accepting true]') {
			up = true
			break
		}
	}
	if !up {
		out := os.read_file(os.join_path(tmp, 'daemon.log')) or { '' }
		panic('fabric-serve never came up: ${out}')
	}

	client_open := '[\$fabric:open "xsp://127.0.0.1:${port}" {tenant: "acme" did: "${sb_client_did}" seed: [\$bytes:from-hex "${sb_client_seed_hex}"]}]'
	pub6 := sb_write(tmp, 'publish6.cx', "[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
		'[?let [= \$f ${client_open}]\n' +
		'      [= \$a [\$fabric:publish \$f "evidence" [evidence [id "e1"]] {}]]\n' +
		'      [= \$b [\$fabric:publish \$f "evidence" [evidence [id "e2"]] {}]]\n' +
		'      [= \$c [\$fabric:publish \$f "evidence" [evidence [id "e3"]] {}]]\n' +
		'      [= \$d [\$fabric:publish \$f "evidence" [evidence [id "e4"]] {}]]\n' +
		'      [= \$e [\$fabric:publish \$f "evidence" [evidence [id "e5"]] {}]]\n' +
		'  [out [\$fabric:publish \$f "evidence" [evidence [id "e6"]] {}]]]\n')
	pout := sb_run('--allow-net=127.0.0.1:${port}', pub6)
	assert pout.contains('seq=6'), 'seed publishes failed: ${pout}'

	jbind := '{url: "xsp://127.0.0.1:${port}", stream: "acts", tenant: "acme", did: "${sb_client_did}", seed: [\$bytes:from-hex "${sb_client_seed_hex}"]}'
	src := '{fabric: "xsp://127.0.0.1:${port}", stream: "evidence", group: "gb", verb: :evidence, actor: "ingest", tenant: "acme", did: "${sb_client_did}", seed: [\$bytes:from-hex "${sb_client_seed_hex}"]}'
	w := sb_write(tmp, 'worker.cx', "[?lib 'cx-stdlib/bytes' :as bytes]\n" + sb_component +
		'[?let [= \$rt [\$xap:run {tenant: "acme" journal: ${jbind} sources: [${src}]}]]\n' +
		'      [= \$w [?sleep 4s]]\n' +
		'  [out [\$count [\$xap:state \$rt "/evidence"]]]]\n')
	wout := sb_run('--allow-net=127.0.0.1:${port}', w)
	assert wout.contains('[out 6]'), 'batched ingest did not fold all six entries: ${wout}'

	// the pipelined appends landed IN ORDER on the acts stream.
	obs := sb_write(tmp, 'observe.cx', "[?lib 'cx-fabric' :as fabric]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
		"[?lib 'cx-stdlib/format' :as format]\n" +
		'[?let [= \$f ${client_open}]\n' +
		'      [= \$s [\$fabric:observe \$f "acts" "event"]]\n' +
		'      [= \$es [?receive from=\$s max=16 deadline=2000]]\n' +
		'  [out [?str \'{[\$count \$es]}|{[\$format:canonical [\$nth \$es 1]]}|{[\$format:canonical [\$nth \$es 6]]}\']]]\n')
	oout := sb_run('--allow-net=127.0.0.1:${port}', obs)
	assert oout.contains('6|'), 'acts stream must carry all six pipelined appends: ${oout}'
	assert oout.contains('e1') && oout.contains('e6'), 'append order lost: ${oout}'
}

// ── #726 — the in-family reference application (reference/shop) ──────────
//
// This is the successor to the external reference XAP that validated the
// authoring process before it became an independent project, and it re-pins
// the "worked reference-instance case" — item 8 of the fixture family in
// xap_grammar_composition.md §9.
//
// It is a REFERENCE, so what it demonstrates matters more than that it
// passes: two base features that know nothing about each other, one
// composite that joins them, and the compose gate deciding which of those
// three is allowed to say what.

fn xa_ref_dir() string {
	return os.real_path(os.join_path(os.dir(@FILE), '..', '..', 'reference', 'shop'))
}

// xa_ref_prog builds a program that loads the reference app's features and
// evaluates `body` with $o / $s / $d bound to the three [feature …] roots.
//
// The `//feature` descendant step is load-bearing: each file opens with a
// `[; … ]` block comment, so the CHILD step `/feature` selects nothing and
// every compose call would silently receive zero features — which composes
// to the empty grammar and reports ok=true. A vacuous pass, and the reason
// this helper exists instead of being inlined per case.
fn xa_ref_prog(body string) string {
	d := xa_ref_dir()
	return "[?lib 'cx-xap' :as xap]\n[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$od [\$cx:parse [\$io:read-file "${d}/orders.feature.cxd"]]]\n' +
		'      [= \$sd [\$cx:parse [\$io:read-file "${d}/shipments.feature.cxd"]]]\n' +
		'      [= \$dd [\$cx:parse [\$io:read-file "${d}/delayed-shipment.feature.cxd"]]]\n' +
		'  [?let [= \$o [\$first [?for [in \$n \$od//feature] [yield \$n]]]]\n' +
		'        [= \$s [\$first [?for [in \$n \$sd//feature] [yield \$n]]]]\n' +
		'        [= \$d [\$first [?for [in \$n \$dd//feature] [yield \$n]]]]\n' +
		'    ${body}]]\n'
}

fn xa_ref_run(body string) string {
	dir := os.join_path(os.temp_dir(), 'cx-xap-ref-${os.getpid()}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	p := xa_write(dir, 'ref.cx', xa_ref_prog(body))
	return xa_run_cx('--allow-read', p)
}

// The three layers compose through the ONE W1-W6 gate, and the two faces of
// the gate agree (§8.1: compose raises iff compose-report says ok=false).
fn test_reference_app_composes_through_the_w_gate() {
	rep := xa_ref_run('[\$xap:compose-report \$o \$s \$d]')
	assert rep.contains('ok=true'), 'the reference app must compose cleanly: ${rep}'
	assert !rep.contains('conflict'), 'no conflicts expected: ${rep}'

	// …and the enforcing face agrees by producing a grammar, not an error.
	// Nine verbs since #865: raise-alert retired with W7 (the derived noun
	// is deriver-reserved; detect is its producer, not a grammar verb).
	g := xa_ref_run('[?let [= \$g [\$xap:compose \$o \$s \$d]] [\$count \$g//verb]]')
	assert g == '9', 'composed grammar must carry all nine qualified verbs, got ${g}'
}

// A BASE feature may not name another feature's verbs — that coupling is
// what the composition model exists to prevent, and W4 enforces it. The
// reference app's shipments.feature.cxd carries a comment explaining why
// its cross-feature rules live on the composite instead; this pins that the
// explanation is TRUE rather than folklore.
fn test_reference_app_base_feature_may_not_reach_across() {
	// shipments with an added cross-feature ordering rule → W4 conflict.
	body := "[\$xap:compose-report \$o [?element \"feature\" [?attr \"name\" \"reaching\"]\n" +
		'  [?element "nouns" [?element "noun" [?attr "name" "x"] [?element "field" [?attr "name" "id"] [?attr "type" "text"]]]]\n' +
		'  [?element "verbs" [?element "verb" [?attr "name" "go"] [?attr "effect" "observe"]\n' +
		'     [?element "intent" [?element "do" [?attr "name" "go"]]]]]\n' +
		'  [?element "rules" [?element "rule" [?attr "name" "reach"] [?attr "kind" "ordering"]\n' +
		'     [?attr "verb" "reaching/go"] [?attr "after" "orders/place-order"]\n' +
		'     [?element "statement" "reaches across"]]]\n' +
		'  [?element "requirements" [?element "requirement" [?attr "kind" "domain"]\n' +
		'     [?element "statement" "s"]]]]]'
	rep := xa_ref_run(body)
	assert rep.contains('ok=false'), 'a base feature reaching across must be refused: ${rep}'
	assert rep.contains(':w4'), 'the refusal must be a W4 conflict: ${rep}'
}

// rho over the reference grammar — the whole of §5 in one case, using the
// deliberately-shared `highlight` term the two bases both define.
fn test_reference_app_rho_resolution() {
	// unique owner: only shipments defines `ship`
	assert xa_ref_run('[\$xap:resolve [\$xap:compose \$o \$s \$d] "ship"]') == 'shipments/ship'

	// qualified always wins (step 1) — untouched by the ambiguity below
	assert xa_ref_run('[\$xap:resolve [\$xap:compose \$o \$s \$d] "orders/highlight"]') == 'orders/highlight'

	// ambiguity is a VALUE listing every candidate, never a guess (step 4)
	amb := xa_ref_run('[\$xap:resolve [\$xap:compose \$o \$s \$d] "highlight"]')
	assert amb.contains('CXER4871'), 'bare highlight must be ambiguous: ${amb}'
	assert amb.contains('orders/highlight'), 'candidate list must name orders: ${amb}'
	assert amb.contains('shipments/highlight'), 'candidate list must name shipments: ${amb}'

	// unknown is its own value, not a crash
	unk := xa_ref_run('[\$xap:resolve [\$xap:compose \$o \$s \$d] "teleport"]')
	assert unk.contains('CXER4872'), 'unknown term must refuse: ${unk}'
}

// N-COMPOSE-1 (no silent rebinding) — the before/after pair. With `orders`
// alone the utterance resolves; enabling `shipments` may only ever turn it
// into an ambiguity that STILL LISTS the original answer. It must never
// quietly come to mean shipments/highlight.
fn test_reference_app_enabling_a_feature_never_rebinds_an_utterance() {
	before := xa_ref_run('[\$xap:resolve [\$xap:compose \$o] "highlight"]')
	assert before == 'orders/highlight', 'with orders alone: ${before}'

	after := xa_ref_run('[\$xap:resolve [\$xap:compose \$o \$s] "highlight"]')
	assert after.contains('CXER4871'), 'after enabling shipments it must ask, not decide: ${after}'
	assert after.contains('orders/highlight'), 'the prior answer must remain a candidate: ${after}'
	assert after != 'shipments/highlight', 'SILENT REBINDING — the N-COMPOSE-1 violation'
}

// Signature derivation (§6): a composite's derived verb takes the strongest
// signature of its constituents. `escalate` names shipments/ship (act,
// shared, irreversible) and orders/cancel-order, so it cannot be gentler
// than either — the floor is derived, not declared.
fn test_reference_app_derived_verb_derives_its_signature() {
	v := xa_ref_run('[?let [= \$g [\$xap:compose \$o \$s \$d]]\n' +
		'  [?for [in \$v \$g//verb] [where [= \$v@name "delayed-shipment/escalate"]] [yield \$v]]]')
	assert v.contains('effect=act'), 'derived from an act constituent: ${v}'
	assert v.contains('scope=shared'), 'derived from a shared constituent: ${v}'
	assert v.contains('consequence=irreversible'), 'derived from an irreversible constituent: ${v}'
	assert v.contains('derived=true'), 'must be marked derived: ${v}'
	assert v.contains('shipments/ship'), 'constituents must survive into the grammar: ${v}'
}

// The composed grammar has a stable Tier-1 identity, and composition is
// commutative at the grammar level (§3.1) — the same three features in a
// different order are the same grammar.
fn test_reference_app_grammar_hash_is_order_independent() {
	a := xa_ref_run('[\$xap:grammar-hash [\$xap:compose \$o \$s \$d]]')
	b := xa_ref_run('[\$xap:grammar-hash [\$xap:compose \$d \$s \$o]]')
	assert a.starts_with('sha2-256:'), 'expected a Tier-1 hash, got ${a}'
	assert a == b, 'compose must be commutative at the grammar level:\n  o,s,d ${a}\n  d,s,o ${b}'
}

// ── #726 — the reference app's COMMITTED CASCADE ─────────────────────────
//
// The authored layers say what the shop can MEAN; these pin what happens
// when someone means it: PEP → journal append → ordered bus, with state as
// the fold of the committed stream.
//
// The components are the runtime half of the three features — `bind` is the
// state route, `emits` the intent shape. The FEATURE says what may be said;
// the COMPONENT says what saying it does.
const xa_ref_components = "[?lib 'cx-xap' :as xap]
[\$xap:component orders
  {bind: \"/order\"
   emits: ([do :place-order [id :string] [customer :string]],
           [do :cancel-order [id :string]])
   working-panel: :none}]
[\$xap:component shipments
  {bind: \"/shipment\"
   emits: ([do :ship [id :string] [for-order :string] [carrier :string]])
   working-panel: :none}]
[\$xap:component delayed-shipment
  {bind: \"/delay-alert\"
   emits: ([do :escalate [for-order :string]])
   working-panel: :none}]
"

// xa_ref_cascade_prog is xa_ref_prog plus the components and a live runtime
// over `journal_bind`, with $g (the composed grammar) and $rt bound.
fn xa_ref_cascade_prog(journal_bind string, body string) string {
	d := xa_ref_dir()
	return xa_ref_components +
		"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
		'[?let [= \$od [\$cx:parse [\$io:read-file "${d}/orders.feature.cxd"]]]\n' +
		'      [= \$sd [\$cx:parse [\$io:read-file "${d}/shipments.feature.cxd"]]]\n' +
		'      [= \$dd [\$cx:parse [\$io:read-file "${d}/delayed-shipment.feature.cxd"]]]\n' +
		'  [?let [= \$o [\$first [?for [in \$n \$od//feature] [yield \$n]]]]\n' +
		'        [= \$s [\$first [?for [in \$n \$sd//feature] [yield \$n]]]]\n' +
		'        [= \$d [\$first [?for [in \$n \$dd//feature] [yield \$n]]]]\n' +
		'    [?let [= \$g [\$xap:compose \$o \$s \$d]]\n' +
		'      [?let [= \$rt [\$xap:run {tenant: "shop" journal: ${journal_bind} grammar: \$g\n' +
		'                              derivers: ({name: "detect" produces: "delayed-shipment/delay-alert"\n' +
		'                                          reads: ("orders/order", "shipments/shipment")})}]]\n' +
		'        ${body}]]]]\n'
}

fn xa_ref_cascade_run(journal_bind string, body string) string {
	dir := os.join_path(os.temp_dir(), 'cx-xap-refcas-${os.getpid()}')
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	p := xa_write(dir, 'cas.cx', xa_ref_cascade_prog(journal_bind, body))
	return xa_run_cx('--allow-read --allow-write', p)
}

// The human principal is the root of the chain: its acts need no delegation,
// commit as QUALIFIED intents (the grammar is attached), and the state route
// is the FOLD of what committed.
fn test_reference_cascade_principal_commits_and_state_folds() {
	out := xa_ref_cascade_run('{url: "mem://shop", stream: "acts"}',
		'[?let [= \$a [\$xap:emit \$rt [do :place-order [id "o-1"] [customer "ada"]] {actor: "principal:fulfilment"}]]\n' +
		'      [= \$b [\$xap:emit \$rt [do :place-order [id "o-2"] [customer "grace"]] {actor: "principal:fulfilment"}]]\n' +
		'  [probe [committed \$a] [orders [\$count [\$xap:state \$rt "/order"]]]]]')
	assert out.contains('orders 2'), 'two commits must fold to two: ${out}'
	// the grammar is attached, so the journal carries the QUALIFIED intent
	assert out.contains("'orders/place-order'"), 'the committed intent must be qualified: ${out}'
}

// N-COMPOSE-2 at the cascade: a composite cannot launder authority. The
// agent holds nothing, so the emit is refused — and the denial names a
// CONSTITUENT, because the wrapper's own name is not a thing you can hold.
fn test_reference_cascade_composite_refuses_naming_the_constituent() {
	out := xa_ref_cascade_run('{url: "mem://shop", stream: "acts"}',
		'[?let [= \$r [\$xap:emit \$rt [do :escalate [for-order "o-1"]] {actor: "agent:expediter"}]]\n' +
		// #853 — $r is a REFUSAL. A computed err in element child position now
		// propagates (code.md §6.4.1), so the refusal is shown by reading its
		// parts (path navigation does not propagate), which keeps BOTH the
		// labelled slot and the sibling count this case asserts on.
		'  [probe [refused [code \$r@code] [message \$r@message]]\n' +
		'         [commits [\$count [\$xap:state \$rt "/delay-alert"]]]]]')
	assert out.contains('CXER4850'), 'an ungranted agent must be refused: ${out}'
	assert out.contains('orders/cancel-order') || out.contains('shipments/ship'),
		'the denial must name a CONSTITUENT, not the wrapper: ${out}'
	assert !out.contains('not granted "delayed-shipment/escalate"'),
		'the denial named the wrapper — authority was decided over the wrong thing: ${out}'
	// The PEP decides BEFORE the append, so a refusal leaves nothing to fold.
	// counts ESCALATE COMMITS on that route, not computed alerts — the
	// derived noun's join is not evaluated by anything (#840).
	assert out.contains('commits 0'), 'a refused emit must commit nothing: ${out}'
}

// The dial IS delegation issuance, and it is revocable. Granting BOTH
// constituents admits the composite; revoking either flips the same emit
// back to refused — and why-allowed reports the constituent decisions with
// authority traced to the human (N-CONTROL-2).
fn test_reference_cascade_dial_admits_then_revoke_refuses() {
	out := xa_ref_cascade_run('{url: "mem://shop", stream: "acts"}',
		'[?let [= \$d1 [\$xap:dial \$rt [from id="principal:fulfilment"] [to id="agent:expediter"]\n' +
		'                              [scope \'shipments/ship\'] [setting :semi-auto]]]\n' +
		'      [= \$d2 [\$xap:dial \$rt [from id="principal:fulfilment"] [to id="agent:expediter"]\n' +
		'                              [scope \'orders/cancel-order\'] [setting :semi-auto]]]\n' +
		'  [?let [= \$ok [\$xap:emit \$rt [do :escalate [for-order "o-1"]] {actor: "agent:expediter"}]]\n' +
		'        [= \$why [\$xap:why-allowed \$rt [do :escalate [for-order "o-1"]] {actor: "agent:expediter"}]]\n' +
		'    [?let [= \$rev [\$xap:revoke \$rt "d-dial-shipments/ship"]]\n' +
		'      [?let [= \$after [\$xap:emit \$rt [do :escalate [for-order "o-2"]] {actor: "agent:expediter"}]]\n' +
		// #853 — $after is the post-revoke REFUSAL, so it is rendered from its
		// parts rather than embedded; $ok and $why are ordinary values and stay
		// as they were.
		'        [probe [admitted \$ok] [why \$why]\n' +
		'               [after-revoke [code \$after@code] [message \$after@message]]\n' +
		'               [commits [\$count [\$xap:state \$rt "/delay-alert"]]]]]]]]')
	assert out.contains("[do 'delayed-shipment/escalate'"),
		'both constituent grants must admit the composite, as a qualified intent: ${out}'
	assert out.contains("allowed='true'"), 'why-allowed must agree with the admit: ${out}'
	assert out.contains('accountable principal=principal:fulfilment'),
		'authority must trace to a human (N-CONTROL-2): ${out}'
	assert out.contains('after-revoke') && out.contains('shipments/ship'),
		'revoking a constituent must refuse the composite again, naming it: ${out}'
	assert out.contains('commits 1'),
		'exactly one escalate committed — the refused ones appended nothing: ${out}'
}

// State survives the process. A SECOND runtime over the same journal
// binding re-folds the committed stream at boot — no re-emit; the journal is
// the hand-off. (The in-memory `mem://` binding is per-process, so this uses
// a real file store, which is what makes the re-fold meaningful.)
fn test_reference_cascade_state_refolds_from_the_journal() {
	dir := os.join_path(os.temp_dir(), 'cx-xap-refold-${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	bind := '{url: "file://${dir}/journal", stream: "acts"}'

	first := xa_ref_cascade_run(bind,
		'[?let [= \$a [\$xap:emit \$rt [do :place-order [id "o-1"] [customer "ada"]] {actor: "principal:fulfilment"}]]\n' +
		'      [= \$b [\$xap:emit \$rt [do :place-order [id "o-2"] [customer "grace"]] {actor: "principal:fulfilment"}]]\n' +
		'  [probe [orders [\$count [\$xap:state \$rt "/order"]]]]]')
	assert first.contains('orders 2'), 'first runtime did not fold two commits: ${first}'

	// a FRESH runtime, same binding, no emits at all
	again := xa_ref_cascade_run(bind, '[probe [orders [\$count [\$xap:state \$rt "/order"]]]]')
	assert again.contains('orders 2'),
		'a fresh runtime must re-fold the committed stream at boot: ${again}'
}

// ── #865 §4.2 — derivation: the deriver as actor ─────────────────────────
//
// The derived noun's ONLY producer is the deriver bound at run assembly.
// Positive: [$xap:derive] folds the record into the noun's route under
// `actor: deriver:<name>`. Negatives: an unbound grammar refuses assembly
// (CXER4875, naming the noun); a wrong claimant refuses; W7 refuses a verb
// that tries to [writes] a derived noun back into existence.

fn test_reference_derive_folds_under_the_deriver_actor() {
	out := xa_ref_cascade_run('{url: "mem://shop", stream: "acts"}',
		'[?let [= \$d [\$xap:derive \$rt {deriver: "detect" noun: "delayed-shipment/delay-alert"\n' +
		'                                record: [delay-alert [for-order "o-1"] [customer "ada"]\n' +
		'                                                     [promised-at "2026-08-01"]]}]]\n' +
		'  [probe [committed \$d]\n' +
		'         [alerts [\$count [\$xap:state \$rt "/delay-alert"]]]\n' +
		'         [who [?for [in \$a [\$xap:state \$rt "/delay-alert"]]\n' +
		'                [yield [\$concat "" \$a/actor]]]]]]')
	assert out.contains('alerts 1'), 'the derived record must fold into /delay-alert: ${out}'
	assert out.contains('deriver:detect'),
		'the fold must carry the deriver actor — attribution is the point: ${out}'
}

fn test_reference_derive_refuses_a_claimant_that_is_not_the_binding() {
	out := xa_ref_cascade_run('{url: "mem://shop", stream: "acts"}',
		'[?let [= \$d [\$xap:derive \$rt {deriver: "impostor" noun: "delayed-shipment/delay-alert"\n' +
		'                                record: [delay-alert [for-order "o-1"]]}]]\n' +
		'  [probe [refused [code \$d@code] [message \$d@message]]\n' +
		'         [alerts [\$count [\$xap:state \$rt "/delay-alert"]]]]]')
	assert out.contains('bound to deriver "detect"'),
		'a wrong claimant must be refused naming the real binding: ${out}'
	assert out.contains('alerts 0'), 'a refused derivation must fold nothing: ${out}'
}

// R8.3: a grammar whose derived noun has NO bound deriver refuses at run
// assembly — a named refusal, never a silently empty queue.
fn test_reference_run_refuses_an_unproduced_derived_noun() {
	d := xa_ref_dir()
	prog := xa_ref_components +
		"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/cx' :as cx]\n" +
